  .split('\n')
  .map(line => line.trim())
  .filter(line => {
    const lower = line.toLowerCase();
    return (
      line.length > 0 &&
      !lower.startsWith('protection de datos') &&
      !lower.includes('facebook') &&
      !lower.includes('linkedin') &&
      !lower.includes('twitter') &&
      !lower.includes('instagram') &&
