const html = $input.first().json.data; // El HTML completo de la web

// 1. Eliminamos scripts y estilos
let clean = html
  .replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, '')
  .replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, '');

// 2. Eliminamos el resto de etiquetas HTML
clean = clean.replace(/<[^>]+>/g, '');

// 3. Decodificamos entidades HTML (como &nbsp;, &eacute;, etc)
const decode = (str) => {
  return str
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;/g, "'")
    .replace(/&#x2F;/g, '/')
    .replace(/&hellip;/g, '...')
    .replace(/\s{2,}/g, ' ')
    .trim();
};

clean = decode(clean);

// 4. Devolvemos el texto limpio como output
return [{ plainText: clean }];

const raw = $('Edit Fields4').first().json.html_body;

// 1. Eliminar "**" del título (solo lo dejamos como texto plano)
let text = raw.replace(/^\*\*(.*?)\*\*/gm, '$1');

// 2. Eliminar asteriscos que marcan negrita
text = text.replace(/\*\*(.*?)\*\*/g, '$1');

// 3. Quitar cabeceras tipo "###"
text = text.replace(/^#+\s*/gm, '');

// 4. Quitar separadores tipo "---"
text = text.replace(/^-{2,}$/gm, '');

// 5. Normalizar espacios y saltos de línea
text = text.replace(/\n{3,}/g, '\n\n').trim();

// 6. Añadir 🔹 delante de los subtítulos numerados (pero no al título)
text = text.replace(/^(\d+\.\s)/gm, '🔹 $1');

// 7. También aplicar 🔹 a "Conclusión" si aparece
text = text.replace(/^Conclusión/gm, '🔹 Conclusión');

return {
  json: {
    cleanText: text
  }
};

const text = $('Limpiamos texto ChatGPT2').first().json.cleanText;

let requests = [];
const lines = text.split('\n');
let cursor = 0;

// TITULO PRINCIPAL (primera línea)
if (lines.length > 0) {
  const title = lines[0];
  requests.push({
    updateTextStyle: {
      range: {
        startIndex: 1,
        endIndex: title.length + 1
      },
      textStyle: {
        bold: true,
        fontSize: {
          magnitude: 18,
          unit: "PT"
        }
      },
      fields: "bold,fontSize"
    }
  });
  cursor += title.length + 1; // sumar salto de línea
}

// RESTO DE LÍNEAS
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  const length = line.length + 1;

  // Detecta subtítulos tipo "🔹 3. Servicios", "🔹 Conclusión", etc.
  if (/^🔹\s+\d+\.\s+/.test(line) || /^🔹\s+Conclusión/.test(line)) {
    requests.push({
      updateTextStyle: {
        range: {
          startIndex: cursor + 1,
          endIndex: cursor + line.length + 1
        },
        textStyle: {
          bold: true,
          fontSize: {
            magnitude: 14,
            unit: "PT"
          }
        },
        fields: "bold,fontSize"
      }
    });
  }

  cursor += length;
}

return {
  json: {
    requests,
    finalText: text
  }
};

